'use client';

import React, { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import api from '@/lib/api';
import { motion, AnimatePresence } from 'framer-motion';
import { 
    Plus, 
    Search, 
    Filter, 
    Calendar, 
    User, 
    Building2, 
    MoreHorizontal,
    ExternalLink,
    AlertCircle,
    XCircle,
    CheckCircle2,
    CalendarClock,
    ChevronRight,
    MapPin,
    ArrowUpRight
} from 'lucide-react';
import { useUIStore } from '@/store/uiStore';
import { cn } from '@/lib/utils';
import { Skeleton } from '@/components/ui/skeleton';

export default function AdminAllocationsPage() {
    const { setPageTitle } = useUIStore();
    const [searchQuery, setSearchQuery] = useState('');
    const [statusFilter, setStatusFilter] = useState('all');

    React.useEffect(() => {
        setPageTitle('Stall Allocations');
    }, [setPageTitle]);

    const { data: allocationsRaw, isLoading } = useQuery({
        queryKey: ['admin-allocations', statusFilter],
        queryFn: () => api.get('/admin/allocations', { params: { status: statusFilter } }).catch(() => ({ data: { data: [] } })),
    });

    const allocations = (allocationsRaw as any)?.data?.data || [];

    const stats = [
        { label: 'Occupied', count: allocations.filter((a: any) => a.status === 'active').length, color: 'text-brand-600' },
        { label: 'Vacant', count: 12, color: 'text-orange-600' }, // Mock vacant data for matrix
        { label: 'Expiring', count: allocations.filter((a: any) => a.status === 'expired').length, color: 'text-red-600' },
    ];

    return (
        <div className="pb-32 -mx-4 md:-mx-0">
            {/* ── Spatial Occupancy Matrix ── */}
            <div className="grid grid-cols-3 gap-2 px-4 mb-6">
                {stats.map((s, i) => (
                    <div key={i} className="bg-white p-3 rounded-2xl border border-gray-100 shadow-sm flex flex-col items-center">
                        <span className={cn("text-[8px] font-black uppercase tracking-widest mb-1", s.color)}>{s.label}</span>
                        <div className="text-xl font-black text-green-950 tracking-tight">{isLoading ? '...' : s.count}</div>
                    </div>
                ))}
            </div>

            {/* ── Filter Tabs (Scrollable) ── */}
            <div className="px-4 mb-6">
                <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2">
                    {['all', 'active', 'expired', 'revoked'].map((tab) => (
                        <button
                            key={tab}
                            onClick={() => setStatusFilter(tab)}
                            className={cn(
                                "flex-shrink-0 px-5 h-10 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all",
                                statusFilter === tab 
                                    ? 'bg-brand-600 text-white shadow-brand-sm' 
                                    : 'bg-white text-text-muted border border-gray-100'
                            )}
                        >
                            {tab}
                        </button>
                    ))}
                </div>
            </div>

            {/* ── Search Bar ── */}
            <div className="px-4 mb-8">
                <div className="relative group">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-text-muted" size={18} />
                    <input 
                        type="text"
                        placeholder="Search trader or stall number..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full h-12 pl-12 pr-4 bg-white border border-gray-100 rounded-2xl text-sm font-bold shadow-sm outline-none focus:border-brand-300"
                    />
                </div>
            </div>

            {/* ── Allocation Card List ── */}
            <div className="space-y-4 px-4">
                {isLoading ? (
                    [1, 2, 3].map(i => <div key={i} className="h-40 bg-gray-100 rounded-[2.5rem] animate-pulse" />)
                ) : (
                    <AnimatePresence>
                        {allocations.map((item: any) => (
                            <motion.div 
                                initial={{ opacity: 0, y: 10 }}
                                animate={{ opacity: 1, y: 0 }}
                                key={item.id}
                                className="bg-white rounded-[2.5rem] border border-gray-50 shadow-sm overflow-hidden"
                            >
                                <div className="p-6">
                                    <div className="flex items-start justify-between mb-6">
                                        <div className="flex items-center gap-4">
                                            <div className="w-14 h-14 bg-brand-50 text-brand-600 rounded-2xl flex items-center justify-center border border-brand-100">
                                                <Building2 size={28} />
                                            </div>
                                            <div>
                                                <h3 className="text-base font-black text-green-950 uppercase tracking-tight">Stall {item.stall}</h3>
                                                <p className="text-[10px] font-black text-text-muted uppercase tracking-widest flex items-center gap-1.5 mt-1">
                                                    <MapPin size={10} /> Block {item.block}
                                                </p>
                                            </div>
                                        </div>
                                        <div className={cn(
                                            "px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border",
                                            item.status === 'active' ? 'bg-green-50 text-green-700 border-green-100' : 'bg-red-50 text-red-700 border-red-100'
                                        )}>
                                            {item.status}
                                        </div>
                                    </div>

                                    <div className="space-y-4">
                                        <div className="bg-gray-50 p-4 rounded-2xl flex items-center justify-between">
                                            <div className="flex items-center gap-3">
                                                <div className="w-8 h-8 rounded-full bg-white border border-gray-200 flex items-center justify-center overflow-hidden">
                                                    <User size={14} className="text-text-muted" />
                                                </div>
                                                <span className="text-xs font-black text-green-950 truncate max-w-[120px]">{item.trader?.business_name || item.trader}</span>
                                            </div>
                                            <button className="text-brand-600 p-1">
                                                <ArrowUpRight size={16} />
                                            </button>
                                        </div>

                                        <div className="space-y-2">
                                            <div className="flex justify-between text-[9px] font-black text-text-muted uppercase tracking-widest px-1">
                                                <span>Lease Progress</span>
                                                <span>65%</span>
                                            </div>
                                            <div className="h-2 w-full bg-gray-100 rounded-full overflow-hidden">
                                                <div className="h-full bg-brand-500 w-[65%]" />
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                <button className="w-full h-12 bg-gray-950 hover:bg-black flex items-center justify-between px-6 active:scale-[0.98] transition-all">
                                    <span className="text-[10px] font-black text-white uppercase tracking-widest">Manage Allocation Workflow</span>
                                    <ChevronRight size={16} className="text-white/40" />
                                </button>
                            </motion.div>
                        ))}
                    </AnimatePresence>
                )}
            </div>

            {/* ── Floating Resource Adder ── */}
            <button className="fixed bottom-24 right-4 w-14 h-14 bg-brand-600 text-white rounded-full shadow-2xl flex items-center justify-center active:scale-90 transition-all z-40 border-4 border-white">
                <Plus size={24} />
            </button>
        </div>
    );
}

'use client';

import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import api from '@/lib/api';
import { 
    FileText, 
    Clock, 
    CheckCircle2, 
    XCircle, 
    Search, 
    Filter,
    ChevronRight,
    User,
    Store,
    MapPin,
    Zap,
    Loader2,
    Phone,
    CornerDownRight
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { ApiResponse } from '@/types';
import { useUIStore } from '@/store/uiStore';
import { cn } from '@/lib/utils';

export default function AdminApplicationsPage() {
    const { setPageTitle } = useUIStore();

    React.useEffect(() => {
        setPageTitle('Trader Applications');
    }, [setPageTitle]);

    const queryClient = useQueryClient();
    const [selectedId, setSelectedId] = useState<number | null>(null);
    const [filterStatus, setFilterStatus] = useState<string>('pending');
    const [searchQuery, setSearchQuery] = useState('');

    const { data: stats } = useQuery<ApiResponse<any>>({
        queryKey: ['admin-applications-stats'],
        queryFn: () => api.get('/admin/applications/stats'),
    });

    const { data: appsData, isLoading } = useQuery<ApiResponse<any>>({
        queryKey: ['admin-applications', filterStatus],
        queryFn: () => api.get('/admin/applications', { params: { status: filterStatus } }),
    });

    const applications: any[] = appsData?.data?.data || [];
    const selectedApp = applications.find(a => a.id === selectedId);

    const reviewMutation = useMutation({
        mutationFn: ({ id, status, notes, stallId }: { id: number, status: string, notes: string, stallId?: number }) => 
            api.post(`/admin/applications/${id}/action`, { status, notes, stall_id: stallId }),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['admin-applications'] });
            queryClient.invalidateQueries({ queryKey: ['admin-applications-stats'] });
            setSelectedId(null);
        }
    });

    const handleAction = (status: 'approved' | 'rejected') => {
        if (!selectedId) return;
        reviewMutation.mutate({
            id: selectedId,
            status,
            notes: status === 'approved' ? 'Stall allocated successfully.' : 'Does not meet requirements.',
            stallId: selectedApp?.preferred_stall_id || undefined
        });
    };

    return (
        <div className="pb-32 -mx-4 md:-mx-0">
            {/* ── Summary Matrix (3-col Mobile) ── */}
            <div className="grid grid-cols-3 gap-2 px-4 mb-6">
                {[
                    { id: 'pending', label: 'Pending', count: stats?.data.pending, color: 'text-amber-600' },
                    { id: 'approved', label: 'Approv.', count: stats?.data.approved, color: 'text-brand-600' },
                    { id: 'rejected', label: 'Reject.', count: stats?.data.rejected, color: 'text-rose-600' }
                ].map((s) => (
                    <button 
                        key={s.id} 
                        onClick={() => setFilterStatus(s.id)}
                        className={cn(
                            "bg-white p-3 rounded-2xl border flex flex-col items-center transition-all active:scale-95",
                            filterStatus === s.id ? "border-brand-600 ring-4 ring-brand-50" : "border-gray-100 shadow-sm"
                        )}
                    >
                        <span className={cn("text-[9px] font-black uppercase tracking-widest mb-1", s.color)}>{s.label}</span>
                        <div className="text-xl font-black text-green-950 tracking-tight">{isLoading ? '...' : s.count ?? 0}</div>
                    </button>
                ))}
            </div>

            {/* ── Search & Filters ── */}
            <div className="px-4 mb-8">
                <div className="relative group">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-text-muted group-focus-within:text-brand-600" size={18} />
                    <input 
                        type="text"
                        placeholder="Search traders or stall requests..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full h-12 pl-12 pr-4 bg-white border border-gray-100 rounded-2xl text-sm font-bold shadow-sm outline-none focus:border-brand-300"
                    />
                </div>
            </div>

            {/* ── Applications List ── */}
            <div className="space-y-4 px-4">
                {isLoading ? (
                    [1, 2, 3].map(i => <div key={i} className="h-32 bg-gray-100 rounded-3xl animate-pulse" />)
                ) : applications.length === 0 ? (
                    <div className="py-20 text-center">
                        <FileText size={48} className="mx-auto text-gray-200 mb-4" />
                        <h3 className="text-lg font-black text-green-950 tracking-tight">Kila kitu shwari.</h3>
                        <p className="text-xs font-bold text-text-muted uppercase tracking-widest mt-1">No pending applications found.</p>
                    </div>
                ) : (
                    <AnimatePresence>
                        {applications.map((app) => (
                            <motion.div 
                                layoutId={`app-${app.id}`}
                                key={app.id} 
                                onClick={() => setSelectedId(app.id)}
                                className="bg-white rounded-[2rem] border border-gray-50 shadow-sm overflow-hidden active:scale-[0.98] transition-all cursor-pointer"
                            >
                                <div className="p-5">
                                    <div className="flex items-center gap-4 mb-4">
                                        <div className="w-12 h-12 bg-brand-50 text-brand-600 rounded-2xl flex items-center justify-center">
                                            <Store size={24} />
                                        </div>
                                        <div className="flex-1 min-w-0">
                                            <h3 className="text-base font-black text-green-950 uppercase tracking-tight truncate">
                                                {app.trader.business_name}
                                            </h3>
                                            <p className="text-[10px] font-black text-brand-600 uppercase tracking-widest">
                                                By {app.trader.user.name}
                                            </p>
                                        </div>
                                        <div className="flex flex-col items-end">
                                            {app.preferred_stall ? (
                                                <span className="px-2 py-0.5 bg-amber-50 text-amber-700 rounded-full text-[9px] font-black uppercase tracking-widest">
                                                    Stall {app.preferred_stall.stall_number}
                                                </span>
                                            ) : (
                                                <span className="px-2 py-0.5 bg-blue-50 text-blue-700 rounded-full text-[9px] font-black uppercase tracking-widest">
                                                    {app.preferred_zone || 'Any'}
                                                </span>
                                            )}
                                        </div>
                                    </div>

                                    {/* Motivation Peek */}
                                    <div className="flex items-start gap-2 bg-gray-50/50 p-3 rounded-xl mb-2">
                                        <CornerDownRight size={12} className="text-text-muted flex-shrink-0 mt-0.5" />
                                        <p className="text-[10px] font-medium text-text-secondary line-clamp-1 italic">
                                            {app.motivation}
                                        </p>
                                    </div>
                                </div>
                                <div className="h-1 bg-brand-500 w-full opacity-0 group-active:opacity-100 transition-all" />
                            </motion.div>
                        ))}
                    </AnimatePresence>
                )}
            </div>

            {/* Application Detail Sheet */}
            <AnimatePresence>
                {selectedId && selectedApp && (
                    <>
                        <motion.div 
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            exit={{ opacity: 0 }}
                            onClick={() => setSelectedId(null)}
                            className="fixed inset-0 bg-green-950/40 backdrop-blur-md z-[90] flex items-end justify-center"
                        >
                            <motion.div 
                                initial={{ y: "100%" }}
                                animate={{ y: 0 }}
                                exit={{ y: "100%" }}
                                className="w-full bg-white rounded-t-[3rem] shadow-2xl flex flex-col max-h-[90vh]"
                                onClick={(e) => e.stopPropagation()}
                            >
                                <div className="p-6 overflow-y-auto no-scrollbar flex-1">
                                    <div className="flex items-start justify-between mb-8">
                                        <div className="flex items-center gap-4">
                                            <div className="w-14 h-14 bg-brand-50 text-brand-600 rounded-2xl flex items-center justify-center">
                                                <Store size={28} />
                                            </div>
                                            <div>
                                                <h2 className="text-xl font-black text-green-950 uppercase tracking-tight">{selectedApp.trader.business_name}</h2>
                                                <p className="text-[10px] font-black text-text-muted uppercase tracking-widest">Submitted {new Date(selectedApp.created_at).toLocaleDateString()}</p>
                                            </div>
                                        </div>
                                        <button onClick={() => setSelectedId(null)} className="p-2 bg-gray-50 rounded-xl">
                                            <XCircle size={24} className="text-text-muted" />
                                        </button>
                                    </div>

                                    <div className="space-y-6">
                                        <div className="bg-gray-50 p-5 rounded-3xl border border-gray-100">
                                            <p className="text-[9px] font-black text-text-muted uppercase tracking-widest mb-3">Applicant Info</p>
                                            <div className="space-y-3">
                                                <div className="flex items-center gap-3">
                                                    <User size={14} className="text-brand-600" />
                                                    <span className="text-sm font-bold text-green-950">{selectedApp.trader.user.name}</span>
                                                </div>
                                                <div className="flex items-center gap-3">
                                                    <Phone size={14} className="text-brand-600" />
                                                    <span className="text-sm font-bold text-text-secondary">{selectedApp.trader.user.phone}</span>
                                                </div>
                                            </div>
                                        </div>

                                        <div className="space-y-3">
                                            <p className="text-[9px] font-black text-text-muted uppercase tracking-widest">Motivation</p>
                                            <div className="bg-white border border-gray-100 p-5 rounded-3xl text-sm font-medium text-text-secondary leading-relaxed italic">
                                                "{selectedApp.motivation}"
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                <div className="p-6 border-t border-gray-100 bg-white flex gap-3">
                                    <button 
                                        disabled={reviewMutation.isPending}
                                        onClick={() => handleAction('rejected')}
                                        className="flex-1 h-14 border border-rose-100 text-rose-600 rounded-2xl font-black text-[10px] uppercase tracking-widest active:bg-rose-50 transition-all"
                                    >
                                        Reject
                                    </button>
                                    <button 
                                        disabled={reviewMutation.isPending}
                                        onClick={() => handleAction('approved')}
                                        className="flex-[2] h-14 bg-brand-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl shadow-brand-900/10 flex items-center justify-center gap-2"
                                    >
                                        {reviewMutation.isPending ? <Loader2 className="animate-spin" size={16} /> : <Zap size={16} />}
                                        Approve & Allocate
                                    </button>
                                </div>
                            </motion.div>
                        </motion.div>
                    </>
                )}
            </AnimatePresence>
        </div>
    );
}

'use client';

import React, { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import api from '@/lib/api';
import { motion, AnimatePresence } from 'framer-motion';
import { 
    History, 
    Search, 
    Filter, 
    Download, 
    Terminal, 
    User, 
    ShieldAlert, 
    Globe,
    ExternalLink,
    ChevronRight,
    SearchCode,
    Cpu,
    ArrowRight,
    Activity,
    Shield
} from 'lucide-react';
import { useUIStore } from '@/store/uiStore';
import { cn } from '@/lib/utils';

export default function AdminAuditLogPage() {
    const { setPageTitle } = useUIStore();
    const [searchQuery, setSearchQuery] = useState('');

    React.useEffect(() => {
        setPageTitle('Platform Governance');
    }, [setPageTitle]);

    const { data: auditDataRaw, isLoading } = useQuery({
        queryKey: ['admin-audit-logs'],
        queryFn: () => api.get('/admin/audit-logs').catch(() => ({ data: [] })),
    });

    const logs = (auditDataRaw as any)?.data || [
        { id: 100, timestamp: '2025-01-27T08:30:00Z', admin: 'John Maina', action: 'Trader Verified', resource: 'Mama Wanjiru', before: 'pending', after: 'verified', ip: '192.168.1.45', severity: 'low' },
        { id: 99, timestamp: '2025-01-27T07:15:00Z', admin: 'Sarah Kamau', action: 'Stall Allocated', resource: 'Stall B4 → Tech Safi', before: 'vacant', after: 'occupied', ip: '192.168.1.12', severity: 'medium' },
        { id: 98, timestamp: '2025-01-26T16:45:00Z', admin: 'John Maina', action: 'Fee Waived', resource: 'Ochieng Fish (Dec 2024)', before: 'unpaid', after: 'waived', ip: '192.168.1.45', severity: 'high' },
        { id: 97, timestamp: '2025-01-26T14:20:00Z', admin: 'System', action: 'Notice Expired', resource: 'Market Maint.', before: 'active', after: 'expired', ip: '127.0.0.1', severity: 'info' },
    ];

    const stats = [
        { label: 'Actions (24h)', value: '142', color: 'text-brand-600', icon: Activity },
        { label: 'Critical', value: '3', color: 'text-rose-600', icon: ShieldAlert },
        { label: 'Integrity', value: '99.9%', color: 'text-blue-600', icon: Shield },
    ];

    const getSeverityStyles = (severity: string) => {
        switch (severity) {
            case 'high': return 'bg-rose-50 text-rose-700 border-rose-100';
            case 'medium': return 'bg-amber-50 text-amber-700 border-amber-100';
            case 'low': return 'bg-green-50 text-green-700 border-green-100';
            default: return 'bg-gray-50 text-gray-500 border-gray-100';
        }
    };

    return (
        <div className="pb-32 -mx-4 md:-mx-0">
            {/* ── Integrity Matrix (3-col Mobile) ── */}
            <div className="grid grid-cols-3 gap-2 px-4 mb-6">
                {stats.map((s, i) => (
                    <div key={i} className="bg-white p-3 rounded-2xl border border-gray-100 shadow-sm flex flex-col items-center text-center">
                        <span className={cn("text-[8px] font-black uppercase tracking-widest mb-1", s.color)}>{s.label}</span>
                        <div className="text-sm font-black text-green-950 tracking-tight">
                            {isLoading ? '...' : s.value}
                        </div>
                    </div>
                ))}
            </div>

            {/* ── Forensic Triage Search ── */}
            <div className="px-4 mb-8">
                <div className="relative group">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-text-muted group-focus-within:text-brand-600" size={18} />
                    <input 
                        type="text"
                        placeholder="Search action or resource..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full h-12 pl-12 pr-4 bg-white border border-gray-100 rounded-2xl text-sm font-bold shadow-sm outline-none focus:border-brand-300 focus:ring-4 focus:ring-brand-50"
                    />
                </div>
            </div>

            {/* ── Audit Hub Cards ── */}
            <div className="space-y-4 px-4">
                {isLoading ? (
                    [1, 2, 3].map(i => <div key={i} className="h-40 bg-gray-100 rounded-[2.5rem] animate-pulse" />)
                ) : (
                    <AnimatePresence mode="wait">
                        {logs.filter((log: any) => 
                            log.action.toLowerCase().includes(searchQuery.toLowerCase()) || 
                            log.resource.toLowerCase().includes(searchQuery.toLowerCase())
                        ).map((log: any) => (
                            <motion.div 
                                initial={{ opacity: 0, y: 10 }}
                                animate={{ opacity: 1, y: 0 }}
                                key={log.id}
                                className="bg-white rounded-[2.5rem] border border-gray-50 shadow-sm overflow-hidden"
                            >
                                <div className="p-6">
                                    <div className="flex items-start justify-between mb-5">
                                        <div className="flex items-center gap-4">
                                            <div className="w-12 h-12 bg-gray-950 text-white rounded-2xl flex items-center justify-center">
                                                <Terminal size={24} className="text-brand-400" />
                                            </div>
                                            <div>
                                                <h4 className="text-sm font-black text-green-950 uppercase tracking-tight leading-none mb-1.5">
                                                    {log.action}
                                                </h4>
                                                <div className="flex items-center gap-2">
                                                    <span className="text-[10px] font-black text-text-muted uppercase tracking-widest">
                                                        By {log.admin}
                                                    </span>
                                                </div>
                                            </div>
                                        </div>
                                        <div className={cn(
                                            "px-2.5 py-1 rounded-full text-[8px] font-black uppercase tracking-widest border",
                                            getSeverityStyles(log.severity)
                                        )}>
                                            {log.severity}
                                        </div>
                                    </div>

                                    {/* Action Resource Peek */}
                                    <div className="bg-gray-50/80 p-4 rounded-3xl border border-gray-100 mb-6">
                                        <div className="flex items-center gap-2 mb-2">
                                            <Cpu size={12} className="text-brand-600" />
                                            <span className="text-[10px] font-black text-green-950 uppercase tracking-widest truncate">{log.resource}</span>
                                        </div>
                                        <div className="flex items-center justify-between font-mono text-[9px] bg-white p-2 rounded-xl border border-gray-50">
                                            <span className="text-rose-400 line-through truncate max-w-[80px]">{log.before}</span>
                                            <ArrowRight size={10} className="text-gray-300 mx-2 flex-shrink-0" />
                                            <span className="text-brand-600 font-black truncate max-w-[80px]">{log.after}</span>
                                        </div>
                                    </div>

                                    <div className="flex gap-2">
