        { label: 'Avg Reads', value: '1.2k', color: 'text-blue-600' },
    ];

    const getTypeStyles = (type: string) => {
        switch (type) {
            case 'urgent': return "bg-red-50 text-red-700 border-red-100 ring-4 ring-red-500/10";
