                                        setLanguage(lang);
                                        updateProfileMutation.mutate({ preferred_language: lang });
                                    }}
                                    className={`px-4 py-1.5 text-[10px] font-black uppercase rounded-lg transition-all ${
                                        language === lang ? 'bg-brand-600 text-white shadow-md' : 'text-text-muted'
                                    }`}
