import { useUIStore } from '@/store/uiStore';
import { useTranslation } from '@/hooks/useTranslation';

interface Complaint {
    id: number;
    subject: string;
    description: string;
    category: string;
    status: 'open' | 'in_review' | 'resolved' | 'closed';
    priority: number;
    admin_response: string | null;
    created_at: string;
