                        </a>
                    </div>
                </div>

                {/* Product */}
                <div className="flex items-center justify-between bg-gray-50 rounded-xl px-4 py-3">
                    <div>
                        <p className="font-bold text-text-primary text-sm">{order.product.name}</p>
                        <p className="text-xs text-text-secondary">
