'use client';

import React from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import api from '@/lib/api';
import { 
    Heart, 
    Bell, 
    BellOff, 
    Trash2, 
    ShoppingBag, 
    Store, 
    ChevronRight,
    Loader2,
    ArrowUpRight,
    TrendingDown,
    MapPin
} from 'lucide-react';
import { useRouter } from 'next/navigation';
import DashboardLayout from '@/components/shared/DashboardLayout';
import { motion, AnimatePresence } from 'framer-motion';
import { ApiResponse } from '@/types';

interface WatchlistItem {
    id: number;
    notify_on_available: boolean;
    product: {
        id: number;
        name: string;
        price: string;
        unit: string;
        stock_status: 'available' | 'low' | 'out_of_stock';
        image_url?: string;
        trader: {
            id: number;
            business_name: string;
        };
    };
}

export default function WatchlistPage() {
    const router = useRouter();
    const queryClient = useQueryClient();

    const { data: watchlistData, isLoading } = useQuery<ApiResponse<WatchlistItem[]>>({
        queryKey: ['watchlist'],
        queryFn: () => api.get('/watchlist'),
    });

    const removeMutation = useMutation({
        mutationFn: (productId: number) => api.delete(`/watchlist/${productId}`),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['watchlist'] });
        }
    });

    const toggleNotifyMutation = useMutation({
        mutationFn: (productId: number) => api.patch(`/watchlist/${productId}/notify`),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['watchlist'] });
        }
    });

    const watchlist = watchlistData?.data || [];

    const getStockBadge = (status: string) => {
        switch (status) {
            case 'available': return 'bg-green-100 text-green-700 border-green-200';
            case 'low': return 'bg-amber-100 text-amber-700 border-amber-200';
            case 'out_of_stock': return 'bg-red-100 text-red-700 border-red-200';
            default: return 'bg-gray-100 text-gray-700 border-gray-200';
        }
    };

    return (
        <DashboardLayout title="Bidhaa Ninazofuata (Watchlist)">
            <div className="space-y-6 pb-20">

                {/* 1. Stats Counter */}
                <div className="bg-green-950 p-8 rounded-[3rem] text-white shadow-xl relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-white/5 rounded-full -mr-16 -mt-16" />
                    <div className="flex items-center gap-4">
                        <div className="w-16 h-16 bg-brand-500 rounded-[1.5rem] flex items-center justify-center text-white shadow-lg">
                            <Heart size={32} fill="currentColor" />
                        </div>
                        <div>
                            <h2 className="text-4xl font-black font-mono tracking-tighter">{watchlist.length}</h2>
                            <p className="text-[10px] font-black uppercase tracking-[0.2em] text-brand-200">Products Followed</p>
                        </div>
                    </div>
                </div>

                {/* 2. List of Items */}
                <div className="space-y-4">
                    {isLoading ? (
                        <div className="py-20 flex flex-col items-center gap-3">
                            <Loader2 className="animate-spin text-brand-600" size={32} />
                            <p className="text-[10px] font-black text-brand-700 uppercase tracking-widest animate-pulse">Safisha Watchlist...</p>
                        </div>
                    ) : watchlist.length > 0 ? (
                        watchlist.map((item) => (
                            <motion.div 
                                key={item.id}
                                layout
                                initial={{ opacity: 0, x: -20 }}
                                animate={{ opacity: 1, x: 0 }}
                                className="bg-white p-5 rounded-[2.5rem] border border-gray-100 shadow-brand-sm group"
                            >
                                <div className="flex gap-4">
                                    <div className="w-24 h-24 bg-neutral-50 rounded-2xl overflow-hidden border border-gray-100 shrink-0 relative">
                                        {item.product.image_url ? (
                                            <img src={item.product.image_url} alt={item.product.name} className="w-full h-full object-cover" />
                                        ) : (
                                            <div className="w-full h-full flex items-center justify-center text-text-muted"><ShoppingBag size={24} /></div>
                                        )}
                                        <div className={`absolute top-2 left-2 px-2 py-0.5 rounded-lg text-[8px] font-black uppercase tracking-tight border ${getStockBadge(item.product.stock_status)}`}>
                                            {item.product.stock_status.replace('_', ' ')}
                                        </div>
                                    </div>

                                    <div className="flex-1 space-y-1 py-1">
                                        <div className="flex items-center justify-between">
                                            <div className="flex items-center gap-1.5 text-text-muted">
                                                <Store size={12} className="text-amber-500" />
                                                <span className="text-[10px] font-bold uppercase tracking-tight">{item.product.trader.business_name}</span>
                                            </div>
                                            <button 
                                                onClick={() => removeMutation.mutate(item.product.id)}
                                                className="text-text-muted hover:text-red-500 transition-colors p-1"
                                            >
                                                <Trash2 size={16} />
                                            </button>
                                        </div>

                                        <h4 className="font-black text-green-950 text-sm">{item.product.name}</h4>
                                        <div className="flex items-baseline gap-1">
                                            <span className="text-[10px] font-bold text-text-muted">KES</span>
                                            <span className="text-xl font-black text-green-950 font-mono tracking-tighter">{item.product.price}</span>
                                            <span className="text-[9px] text-text-muted font-bold lowercase">/{item.product.unit}</span>
                                        </div>

                                        <div className="flex gap-2 mt-2">
                                            <button 
                                                onClick={() => toggleNotifyMutation.mutate(item.product.id)}
                                                className={`flex-1 h-10 rounded-xl flex items-center justify-center gap-2 text-[9px] font-black uppercase tracking-widest transition-all ${
                                                    item.notify_on_available 
                                                        ? 'bg-brand-50 text-brand-600 border border-brand-100' 
                                                        : 'bg-neutral-50 text-neutral-400 border border-neutral-100'
                                                }`}
                                            >
                                                {item.notify_on_available ? <Bell size={14} /> : <BellOff size={14} />}
                                                {item.notify_on_available ? 'Unfollow Stock' : 'Notify on Stock'}
                                            </button>
                                            <button 
                                                onClick={() => router.push(`/trader/${item.product.id}`)}
                                                className="w-10 h-10 bg-neutral-900 text-white rounded-xl flex items-center justify-center active:scale-90 transition-all shadow-lg"
                                            >
                                                <ArrowUpRight size={16} />
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            </motion.div>
                        ))
                    ) : (
                        <div className="py-20 text-center space-y-6">
                            <div className="w-24 h-24 bg-neutral-50 rounded-[2.5rem] flex items-center justify-center text-neutral-200 mx-auto relative">
                                <Heart size={48} className="animate-pulse" />
                                <div className="absolute top-2 right-2 w-4 h-4 bg-brand-500 rounded-full animate-ping" />
                            </div>
                            <div className="space-y-2">
                                <h3 className="text-xl font-black text-green-950">Huna bidhaa unazo fuata</h3>
                                <p className="text-xs text-text-secondary font-medium px-16 leading-relaxed">
                                    Bonyeza alama ya moyo kwenye bidhaa ili kupata taarifa zikiongezwa dukani au zikiwa punguzo.
                                </p>
                            </div>
                            <button 
                                onClick={() => router.push('/')}
                                className="px-10 py-5 bg-brand-600 text-white rounded-[2rem] text-[10px] font-black uppercase tracking-[0.2em] shadow-xl shadow-brand-100 flex items-center gap-3 mx-auto"
                            >
                                <ShoppingBag size={18} /> Gudua Bidhaa (Discover)
                            </button>
                        </div>
                    )}
                </div>

                {/* 3. Personalized Recommendation Banner */}
                <div className="bg-amber-100 p-8 rounded-[3rem] border border-amber-200 flex items-center justify-between">
                    <div className="space-y-1">
                        <div className="flex items-center gap-2 text-amber-600 mb-1">
                            <TrendingDown size={20} />
                            <span className="text-[10px] font-black uppercase tracking-widest">Price Peak Alert</span>
                        </div>
                        <h4 className="text-lg font-black text-amber-900 leading-tight">Zucchini bei imeshuka Leo!</h4>
                        <p className="text-[10px] font-bold text-amber-700/70 uppercase">Fika market ya Kolenyo sasa</p>
                    </div>
                    <div className="w-16 h-16 bg-white rounded-2xl shadow-xl flex items-center justify-center text-amber-500 border border-amber-100 animate-bounce">
                        <MapPin size={24} />
                    </div>
                </div>
            </div>
        </DashboardLayout>
    );
}

'use client';

import React, { useState, useEffect } from 'react';
import { 
    LayoutDashboard, 
    Store, 
    Users, 
    MapPin, 
    Ticket, 
    MessageSquare, 
    FileText, 
    Bell,
    Settings,
    ChevronRight,
    ChevronDown,
    Search,
    BarChart3,
    Map as MapIcon,
    CreditCard,
    ShoppingBag,
    Star,
    UsersRound,
    SquareChartGantt,
    ShieldCheck
} from 'lucide-react';
import { useRouter, usePathname } from 'next/navigation';
import { useTranslation } from '@/hooks/useTranslation';
import { useAuthStore } from '@/store/authStore';
import { Logo } from '../shared/Logo';
import { LanguageToggle } from '../shared/LanguageToggle';
import { motion, AnimatePresence } from 'framer-motion';

export default function AdminSidebar() {
    const router = useRouter();
    const pathname = usePathname();
    const { t } = useTranslation();

    // Track which sections are expanded
    const [expandedSections, setExpandedSections] = useState<string[]>(['Operations']);

    const menuSections = [
        {
            title: 'Operations',
            icon: LayoutDashboard,
            items: [
                { icon: LayoutDashboard, label: t('admin.dashboard_title'), path: '/admin/dashboard' },
                { icon: BarChart3, label: t('common.analytics') || 'Analytics', path: '/admin/analytics' },
                { icon: MapIcon, label: t('common.market_map') || 'Market Map', path: '/admin/map' },
            ]
        },
        {
            title: 'Infrastructure',
            icon: Building2,
            items: [
                { icon: MapPin, label: t('common.markets'), path: '/admin/markets' },
                { icon: Store, label: t('common.stalls'), path: '/admin/stalls' },
                { icon: SquareChartGantt, label: 'Allocations', path: '/admin/allocations' },
            ]
        },
        {
            title: 'Traders & Users',
            icon: Users,
            items: [
                { icon: FileText, label: 'Applications', path: '/admin/applications', badge: 'New' },
                { icon: Users, label: t('common.traders'), path: '/admin/traders' },
                { icon: UsersRound, label: 'User Management', path: '/admin/users' },
            ]
        },
        {
            title: 'Commerce',
            icon: CreditCard,
            items: [
                { icon: Ticket, label: t('common.fees'), path: '/admin/fees' },
                { icon: CreditCard, label: 'Payment History', path: '/admin/payments' },
                { icon: ShoppingBag, label: 'Reservations', path: '/admin/reservations' },
                { icon: Star, label: 'Reviews', path: '/admin/reviews' },
            ]
        },
        {
            title: 'Communication',
            icon: MessageSquare,
            items: [
                { icon: MessageSquare, label: t('common.complaints'), path: '/admin/complaints', badge: 5 },
                { icon: Bell, label: t('common.notifications'), path: '/admin/notices' },
            ]
        },
        {
            title: 'System',
            icon: Settings,
            items: [
                { icon: ShieldCheck, label: 'Audit Log', path: '/admin/audit-log' },
                { icon: Settings, label: t('common.settings'), path: '/admin/settings' },
            ]
        }
    ];

    // Automatically expand the section that contains the current active route
    useEffect(() => {
        const activeSection = menuSections.find(section => 
            section.items.some(item => pathname === item.path)
        );
        if (activeSection && !expandedSections.includes(activeSection.title)) {
            setExpandedSections(prev => [...prev, activeSection.title]);
        }
    }, [pathname]);

    const toggleSection = (title: string) => {
        setExpandedSections(prev => 
            prev.includes(title) 
                ? prev.filter(t => t !== title) 
                : [...prev, title]
        );
    };

    return (
        <aside className="hidden lg:flex flex-col w-[300px] h-screen bg-white border-r border-neutral-100 sticky top-0 left-0 overflow-hidden">
            {/* Logo Area */}
            <div className="p-8 pb-6">
                <div 
                    onClick={() => router.push('/admin/dashboard')} 
                    className="cursor-pointer active:scale-95 transition-transform"
                >
                    <Logo variant="light" width={140} />
                </div>
            </div>

            {/* Scrollable Navigation */}
            <nav className="flex-1 px-4 space-y-2 overflow-y-auto no-scrollbar pb-10">
                {menuSections.map((section, sIdx) => {
                    const isExpanded = expandedSections.includes(section.title);
                    const isAnyItemActive = section.items.some(item => pathname === item.path);

                    return (
                        <div key={sIdx} className="space-y-1">
                            <button
                                onClick={() => toggleSection(section.title)}
                                className={`w-full flex items-center justify-between p-3.5 rounded-2xl transition-all ${
                                    isAnyItemActive && !isExpanded 
                                        ? 'bg-brand-50 text-brand-700' 
                                        : 'text-neutral-400 hover:text-neutral-900 hover:bg-neutral-50'
                                }`}
                            >
                                <div className="flex items-center gap-3">
                                    <span className="text-[10px] font-black uppercase tracking-[0.2em]">
                                        {section.title}
                                    </span>
                                    {isAnyItemActive && !isExpanded && (
                                        <div className="w-1.5 h-1.5 rounded-full bg-brand-600" />
                                    )}
                                </div>
                                {isExpanded ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
                            </button>

                            <AnimatePresence initial={false}>
                                {isExpanded && (
                                    <motion.div
                                        initial={{ height: 0, opacity: 0 }}
                                        animate={{ height: 'auto', opacity: 1 }}
                                        exit={{ height: 0, opacity: 0 }}
                                        transition={{ duration: 0.3, ease: 'circOut' }}
                                        className="overflow-hidden space-y-1 ml-2"
                                    >
                                        {section.items.map((item) => {
                                            const isActive = pathname === item.path;
                                            return (
                                                <button
                                                    key={item.path}
                                                    onClick={() => router.push(item.path)}
                                                    className={`w-full flex items-center justify-between p-3 rounded-xl transition-all group active:scale-[0.98] ${
                                                        isActive 
                                                            ? 'bg-green-950 text-white shadow-lg shadow-green-900/20' 
                                                            : 'text-neutral-600 hover:bg-neutral-50 hover:pl-5'
                                                    }`}
                                                >
                                                    <div className="flex items-center gap-3">
                                                        <item.icon 
                                                            size={16} 
                                                            className={isActive ? 'text-brand-400' : 'text-neutral-400 group-hover:text-green-950 transition-colors'} 
                                                            strokeWidth={isActive ? 2.5 : 2}
                                                        />
                                                        <span className={`text-[13px] font-bold tracking-tight ${isActive ? 'text-white' : ''}`}>
                                                            {item.label}
                                                        </span>
                                                    </div>
                                                    {item.badge && (
                                                        <div className={`px-2 py-0.5 rounded-md text-[8px] font-black ${
                                                            isActive ? 'bg-white/20 text-white' : 'bg-brand-100 text-brand-700'
                                                        }`}>
                                                            {item.badge}
                                                        </div>
                                                    )}
                                                </button>
                                            );
                                        })}
                                    </motion.div>
                                )}
                            </AnimatePresence>
                        </div>
                    );
                })}
            </nav>

            {/* Bottom Section */}
            <div className="p-6 border-t border-neutral-50 bg-neutral-50/30">
                <div className="p-4 bg-white rounded-3xl border border-neutral-100 space-y-4 shadow-sm">
                    <div className="flex items-center justify-between">
                        <p className="text-[10px] font-black text-neutral-400 uppercase tracking-widest">{t('common.language')}</p>
                        <LanguageToggle />
                    </div>

                    <button 
                        onClick={() => {
                            const { logout } = useAuthStore.getState();
                            logout();
                            router.push('/login');
                        }}
                        className="w-full h-14 flex items-center justify-center p-3 rounded-2xl bg-rose-50 text-rose-600 font-black text-[10px] uppercase tracking-[0.2em] hover:bg-rose-100 active:scale-95 transition-all"
                    >
                        Sign Out
                    </button>
                </div>
            </div>
        </aside>
    );
}

