'use client';

import { useState, useCallback, useRef } from 'react';
import api from '@/lib/api';
import { ApiResponse } from '@/types';

type PaymentStatus = 'pending' | 'completed' | 'failed' | 'refunded';

interface MpesaStatusResponse {
    status: PaymentStatus;
    mpesa_transaction_id?: string;
    amount: string;
    paid_at?: string;
}

export const useMpesa = () => {
    const [isPolling, setIsPolling] = useState(false);
    const [status, setStatus] = useState<PaymentStatus | null>(null);
    const [error, setError] = useState<string | null>(null);
    const pollIntervalRef = useRef<NodeJS.Timeout | null>(null);

    const stopPolling = useCallback(() => {
        if (pollIntervalRef.current) {
            clearInterval(pollIntervalRef.current);
            pollIntervalRef.current = null;
        }
        setIsPolling(false);
    }, []);

    const pollStatus = useCallback(async (checkoutRequestId: string) => {
        setIsPolling(true);
        setStatus('pending');
        setError(null);

        // Clear existing interval if any
        if (pollIntervalRef.current) clearInterval(pollIntervalRef.current);

        let attempts = 0;
        const maxAttempts = 20; // ~1 minute of polling (3s intervals)

        pollIntervalRef.current = setInterval(async () => {
            attempts++;

            try {
                const response = await api.get<ApiResponse<MpesaStatusResponse>>(`/payments/mpesa/status/${checkoutRequestId}`);
                const currentStatus = response.data.data.status;

                if (currentStatus === 'completed' || currentStatus === 'failed') {
                    setStatus(currentStatus);
                    stopPolling();
                }

                if (attempts >= maxAttempts) {
                    setError('IMEPITWA NA MUDA (Timed out). If you paid, please check your orders in a moment.');
                    stopPolling();
                }
            } catch (err) {
                console.error('Polling error:', err);
                // We continue polling on error unless it's a 404 (handled by backend as 404 if not found for user)
            }
        }, 3000);
    }, [stopPolling]);

    const initiateStk = async (phoneNumber: string, type: 'reservation' | 'market_fee', targetId: number) => {
        setIsPolling(true);
        setError(null);
        try {
            const response = await api.post<ApiResponse<{ checkout_request_id: string }>>('/payments/mpesa/stkpush', {
                phone_number: phoneNumber,
                type,
                target_id: targetId
            });

            const checkoutId = response.data.data.checkout_request_id;
            pollStatus(checkoutId);
            return checkoutId;
        } catch (err: any) {
            setError(err.response?.data?.message || 'Imeshindwa kutuma ombi (Request failed)');
            setIsPolling(false);
            throw err;
        }
    };

    return {
        initiateStk,
        isPolling,
        status,
        error,
        stopPolling
    };
};

'use client';

import { useCallback } from 'react';
import { useLocaleStore } from '@/store/localeStore';
import en from '@/locales/en.json';
import sw from '@/locales/sw.json';

type TranslationKeys = typeof en;

export function useTranslation() {
  const { locale, toggleLocale, setLocale } = useLocaleStore();

  const translations = locale === 'en' ? en : sw;

  /**
   * Translate a key string (e.g., "common.search")
   */
  const t = useCallback((key: string): string => {
    const keys = key.split('.');
    let result: any = translations;

    for (const k of keys) {
      if (result && result[k]) {
        result = result[k];
      } else {
        // Fallback to English if key missing in Swahili
        let fallback: any = en;
        for (const fk of keys) {
            if (fallback && fallback[fk]) {
                fallback = fallback[fk];
            } else {
                return key; // Final fallback: return the key itself
            }
        }
        return fallback;
      }
    }

    return result as string;
  }, [translations]);

  return { t, locale, toggleLocale, setLocale };
}

'use client';

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import api from '@/lib/api';
import { ApiResponse } from '@/types';

export interface Wallet {
    id: number;
    trader_id: number;
    balance: number;
    currency: string;
    is_active: boolean;
    frequency?: 'daily' | 'weekly';
    last_deduction?: string;
}

export interface WalletTransaction {
    id: number;
    wallet_id: number;
    amount: number;
    type: 'credit' | 'debit';
    description: string;
    reference_type: string | null;
    reference_id: string | null;
    created_at: string;
}

export function useWallet() {
    const queryClient = useQueryClient();

    const { data: walletData, isLoading: walletLoading } = useQuery<ApiResponse<Wallet>>({
        queryKey: ['wallet'],
        queryFn: () => api.get('/trader/wallet'),
    });

    const { data: transactionsData, isLoading: transactionsLoading } = useQuery<ApiResponse<any>>({
        queryKey: ['wallet-transactions'],
        queryFn: () => api.get('/trader/wallet/transactions'),
    });

    const updateFrequency = useMutation({
        mutationFn: (frequency: 'daily' | 'weekly') => 
            api.post('/trader/wallet/frequency', { frequency }),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['wallet'] });
        }
    });

    return {
        wallet: walletData?.data,
        transactions: transactionsData?.data?.data || [],
        walletLoading,
        transactionsLoading,
        updateFrequency
    };
}

import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import api from '@/lib/api';
import { User, ApiResponse } from '@/types';

interface AuthState {
    user: User | null;
    token: string | null;
    isAuthenticated: boolean;
    setAuth: (user: User, token: string) => void;
    logout: () => void;
    refreshUser: () => Promise<void>;
}

export const useAuthStore = create<AuthState>()(
    persist(
        (set, get) => ({
            user: null,
            token: null,
            isAuthenticated: false,

            setAuth: (user, token) => {
                localStorage.setItem('sokomtaa_token', token);
                set({ user, token, isAuthenticated: true });
            },

            logout: () => {
                localStorage.removeItem('sokomtaa_token');
                set({ user: null, token: null, isAuthenticated: false });
            },

            refreshUser: async () => {
                try {
                    const response = await api.get<never, ApiResponse<User>>('/auth/me');
                    set({ user: response.data, isAuthenticated: true });
                } catch (error) {
                    get().logout();
                }
            },
        }),
        {
            name: 'sokomtaa-auth-storage',
            partialize: (state) => ({ user: state.user, token: state.token, isAuthenticated: state.isAuthenticated }),
        }
    )
);
